 public bool Discard(){return !dirty||MessageBox.Show("Há alterações que ainda não foram salvas no site. Descartar e continuar?","Videira",MessageBoxButtons.YesNo,MessageBoxIcon.Question)==DialogResult.Yes;}
 Dictionary<string,object> Selected(){if(grid.CurrentRow==null)return null;var row=grid.CurrentRow.DataBoundItem as SiteListItem;return row==null?null:products.FirstOrDefault(p=>SiteApi.Read(p,"id")==row.id);}
 void Render(){if(grid==null)return;string q=search.Text.Trim();var list=products.Where(p=>String.Join(" ",new[]{SiteApi.Read(p,"name"),SiteApi.Read(p,"category"),SiteApi.Read(p,"country"),SiteApi.Read(p,"grape"),SiteApi.Read(p,"winery")}).IndexOf(q,StringComparison.CurrentCultureIgnoreCase)>=0).Where(p=>filter.SelectedIndex==0||(Convert.ToBoolean(p["active"])==(filter.SelectedIndex==1)));grid.DataSource=list.Select(p=>new SiteListItem{id=SiteApi.Read(p,"id"),name=SiteApi.Read(p,"name"),category=SiteApi.Read(p,"category"),price=p["price"]==null?"Sob consulta":Convert.ToDecimal(p["price"]).ToString("N2"),state=Convert.ToBoolean(p["active"])?"Publicado":"Oculto"}).ToList();}
 async Task LoadProducts(){products=await api.Products();Render();foreach(string c in products.Select(p=>SiteApi.Read(p,"category")).Where(c=>c!="").Distinct())if(!category.Items.Contains(c))category.Items.Add(c);var settings=(object[])await api.Request("/rest/v1/store_settings?select=whatsapp");loading=true;whatsapp.Text=settings.Length==0?"":SiteApi.Read((Dictionary<string,object>)settings[0],"whatsapp");loading=false;}
 void EditSelected(){var p=Selected();if(p==null){Message("Selecione um produto na lista.");return;}if(!Discard())return;loading=true;id=SiteApi.Read(p,"id");name.Text=SiteApi.Read(p,"name");price.Text=p["price"]==null?"":Convert.ToDecimal(p["price"]).ToString("0.00",CultureInfo.GetCultureInfo("pt-BR"));category.Text=SiteApi.Read(p,"category");country.Text=SiteApi.Read(p,"country");grape.Text=SiteApi.Read(p,"grape");winery.Text=SiteApi.Read(p,"winery");image.Text=SiteApi.Read(p,"image_url");description.Text=SiteApi.Read(p,"description");active.Checked=Convert.ToBoolean(p["active"]);featured.Checked=Convert.ToBoolean(p["featured"]);loading=false;dirty=false;Message("Editando "+name.Text+". Clique em Salvar no site para publicar as alterações.");}
 void Reset(){loading=true;id="";foreach(var field in new[]{name,price,country,grape,winery,image,description})field.Clear();category.Text="Tinto";active.Checked=true;featured.Checked=false;loading=false;dirty=false;}
 async Task SaveProduct(){if(name.Text.Trim()=="")throw new Exception("Informe o nome do vinho.");if(category.Text.Trim()=="")throw new Exception("Informe a categoria.");decimal number;object value=null;if(price.Text.Trim()!=""){if(!Decimal.TryParse(price.Text.Trim().Replace('.',','),NumberStyles.AllowDecimalPoint,CultureInfo.GetCultureInfo("pt-BR"),out number)||number<0||number>9999999999m)throw new Exception("Informe um preço válido, usando vírgula para os centavos.");value=Math.Round(number,2);}Uri uri;if(image.Text.Trim()!=""&&(!Uri.TryCreate(image.Text.Trim(),UriKind.Absolute,out uri)||uri.Scheme!="https"))throw new Exception("A foto precisa ter uma URL HTTPS válida.");var p=new Dictionary<string,object>{{"name",name.Text.Trim()},{"category",category.Text.Trim()},{"country",country.Text.Trim()},{"grape",grape.Text.Trim()},{"winery",winery.Text.Trim()},{"image_url",image.Text.Trim()},{"description",description.Text.Trim()},{"price",value},{"active",active.Checked},{"featured",featured.Checked}};await api.Save(p,id);dirty=false;await LoadProducts();Reset();Message("Salvo no site e conferido no servidor. Atualize a loja no navegador para ver o resultado.");}
