public static class SiteStandalone {
 [STAThread] public static void Main(string[] args){if(args.Contains("--connection-test")){try{using(var api=new SiteApi()){var rows=(object[])api.Request("/rest/v1/products?select=id&active=eq.true","GET",null,false).GetAwaiter().GetResult();var contact=(object[])api.Request("/rest/v1/store_settings?select=whatsapp","GET",null,false).GetAwaiter().GetResult();bool denied=false;try{api.Request("/rest/v1/products","POST",new{name="Verificação de acesso do painel",active=false},false).GetAwaiter().GetResult();}catch(Exception ex){denied=ex.Message.Contains("401")||ex.Message.Contains("403");}if(!denied)throw new Exception("A edição anônima não foi bloqueada.");File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"connection-test.txt"),"PASS: conexão HTTPS, leitura do catálogo e do contato; edição sem login bloqueada. Rótulos publicados: "+rows.Length+"; configurações: "+contact.Length);}}catch(Exception ex){File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"connection-test.txt"),"FAIL: "+ex.Message);}return;}Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);var form=new Form{Text="VIDEIRA • Painel do site",Width=1280,Height=860,MinimumSize=new Size(1100,700),StartPosition=FormStartPosition.CenterScreen};var panel=new SitePanel();form.Controls.Add(panel);form.FormClosing+=(s,e)=>{if(!panel.Discard())e.Cancel=true;};if(args.Contains("--preview-site"))form.Shown+=(s,e)=>{var timer=new Timer{Interval=800};timer.Tick+=(a,b)=>{timer.Stop();using(var bmp=new Bitmap(form.Width,form.Height)){form.DrawToBitmap(bmp,new Rectangle(0,0,form.Width,form.Height));bmp.Save(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"painel-site.png"));}form.Close();};timer.Start();};Application.Run(form);}
}
